class PluginUtils(object):
    def restart_uex(self):
        """
        Restart UEx
        :return:
        """
        from ta_ue_plugin_rtg.rpc.uex_connection import UexConnection
        from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall
        import logging
        uex_conn = UexConnection()
        rpc_conn = uex_conn.rpc_conn
        self.rpc_call = RpcCall(rpc_conn, logging.getLogger('ute_ue')).call
        self.rpc_call(method="restart_uex_app", params=None)
